def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_d = 0
    for o in opp:
        if o == 'D':
            opp_d += 1

    if n == 99:
        return 'D'

    if opp_d == n:
        return 'D'

    if opp_d == 0:
        return 'C'

    after_my_D = 0
    after_my_D_D = 0
    for i in range(n - 1):
        if me[i] == 'D':
            after_my_D += 1
            if opp[i + 1] == 'D':
                after_my_D_D += 1

    if last_opp == 'C':
        if n >= 8 and after_my_D >= 1 and after_my_D_D == 0 and opp_d * 10 <= n:
            return 'D'
        if opp_d * 10 > 9 * n:
            return 'D'
        return 'C'

    if n >= 3 and opp[-3:].count('D') >= 3:
        return 'D'

    threshold = max(2, n // 3)

    if last_me == 'D':
        if opp_d <= threshold:
            return 'C'
        return 'D'

    if n >= 2 and opp[-2] == 'D':
        if n >= 3 and me[-2] == 'D' and opp_d <= threshold:
            return 'C'
        return 'D'

    if opp_d <= max(2, n // 10):
        return 'C'

    if opp_d <= threshold:
        return 'D' if rng.random() < 0.4 else 'C'

    return 'D'
